"""Application settings, loaded once at import time."""

import json
import os

_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
_SETTINGS_PATH = os.path.join(_ROOT, "settings.json")

with open(_SETTINGS_PATH, "r", encoding="utf-8") as _fh:
    SETTINGS = json.load(_fh)


def get_setting(key):
    """Return one settings value, or None when the key is absent."""
    return SETTINGS.get(key)
"""Account numbers for statements."""

def account_number(customer_id):
    return "ACCT-{0:04d}".format(int(customer_id))
"""Mailing address lines."""

def format_address(city, region):
    return "{0}, {1}".format(city or "", region or "")
"""Closed-period archive stamps."""

def stamp(year, month):
    return "closed-{0}-{1:02d}".format(year, month)
"""Audit codes. The prefix is not the settings key."""

def code(n):
    return "fee_" + "code" + str(n)
"""Opening balance carried into a period."""

def opening(cents):
    return round(int(cents) / 100.0, 2)
"""Billing contact labels."""

def label(name, email):
    return "{0} <{1}>".format(name, email)
"""Currency minor units."""

def minor_units(code):
    return 0 if code == "JPY" else 2
"""Customer display names."""

def display_name(first, last):
    return "{0} {1}".format(first or "", last or "").strip()
"""Archived discount schedule. Not used by the live total."""

def archived_discount(amount):
    """Old catalog discount. The live total does not call this."""
    archived_fee_rate = 0.15
    if amount is None:
        return 0
    return round(float(amount) * archived_fee_rate, 2)
"""Invoice column labels."""

def heading():
    """The fee_rate column name is historical and unused by the total."""
    column = "fee_rate"
    return "Invoice " + column
"""Package label text."""

def package_label(sku, qty):
    return "{0} x{1}".format(sku, qty)
"""Ledger entry ids."""

def entry_id(day, seq):
    return "L{0}-{1}".format(day, seq)
"""Free-text notes attached to a bill."""

def clip(text, limit=40):
    text = text or ""
    return text if len(text) <= limit else text[:limit] + "..."
"""Billing period bounds."""

def period_key(year, month):
    return "{0}-{1:02d}".format(year, month)
"""Product sku helpers."""

def sku(family, n):
    return "{0}-{1:03d}".format(family, n)
"""Quantity checks."""

def positive(qty):
    return max(int(qty or 0), 0)
"""Receipt numbers."""

def receipt_no(n):
    return "R-{0:06d}".format(int(n))
"""Refund references."""

def refund_ref(receipt):
    return "RF-" + str(receipt)
"""Region codes."""

def region_code(name):
    return (name or "xx")[:2].upper()
"""Reminder copy."""

def reminder_subject(invoice_no):
    return "Reminder for " + str(invoice_no)
"""Print the configured fee for a billing report."""

from app.config import get_setting


def main():
    rate = get_setting("fee_rate")
    if rate is None:
        raise SystemExit("fee_rate is missing")
    print("Report fee: {}".format(rate))


if __name__ == "__main__":
    main()
"""Money rounding."""

def money(value):
    return round(float(value or 0), 2)
"""Send windows."""

def window(hour):
    hour = int(hour) % 24
    return "{0:02d}:00-{1:02d}:00".format(hour, (hour + 1) % 24)
"""Statement titles."""

def title(year, month):
    return "Statement {0}-{1:02d}".format(year, month)
"""Bill status words."""

def status_word(open_bill):
    return "open" if open_bill else "closed"
"""Marginal tax table. This is not the billing settings key."""

def marginal(amount):
    rate = 0.2 if amount and amount > 100 else 0.05
    fee_schedule = {"standard": rate}
    return round(float(amount or 0) * fee_schedule["standard"], 2)

